/**************************
 * Agent type definitions
 **************************/
import { INVALID_ARGUMENT } from "../errors/index.js";
import { getTextFromMemoryParts } from "./memory/memory-interface.js";
// Utility functions for working with message parts and tool calls
/** Return text from parts. */
export function getTextFromParts(parts) {
    return getTextFromMemoryParts(parts);
}
/** Check whether args is present. */
export function hasArgs(part) {
    return "args" in part && part.args !== undefined;
}
/** Input payload for has. */
export function hasInput(part) {
    return "input" in part && part.input !== undefined;
}
/** Return tool arguments. */
export function getToolArguments(part) {
    if (hasArgs(part))
        return part.args;
    if (hasInput(part))
        return part.input;
    const basePart = part;
    throw INVALID_ARGUMENT.create({
        detail: `Tool call part for "${basePart.toolName}" (${basePart.toolCallId}) missing both 'args' and 'input' fields`,
    });
}
